package com.bank.code;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PalindromeDemo {
    private static final Logger log = Logger.getLogger(PalindromeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        PalindromeChecker checker = new PalindromeChecker();
        String[] codes = {"Madam", "RAJESH", "level", "A1b2"};

        for (String code : codes) {
            boolean result = checker.isPalindrome(code);
            log.info(() -> "Code '" + code + "' palindrome? " + result);
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
